/**
 * Test skeleton for Story 1.4: OpenTelemetry + Prometheus + Loki + Grafana 部署
 *
 * AUTO-GENERATED by QA Test Design (Turing, 2026-05-11). Dev MUST keep every
 * static (Unit) scenario passing; runtime scenarios (Integration / E2E /
 * runtime-only Blind-Spot) stay `test.skip` with a pointer to
 * `docs/dev/logs/1.4-dev-log.md` §E2E.
 *
 * Static scenarios parse:
 *   - Helm values YAML via `yaml`
 *   - Dashboard JSON via `JSON.parse`
 *   - Go source / bash script / READMEs via raw text + regex
 *     (matches the deliverable_bindings convention SM/Architect already use).
 *
 * Skip rules:
 *   - File-presence asserts use `existsSync`; Dev's first deliverable is the
 *     file itself (failing assertion is the gate, not a thrown skeleton).
 *   - True runtime checks (cluster-side, container-side, real timing) live as
 *     `test.skip` with the canonical evidence path in their reason.
 *
 * Test Design: docs/qa/assessments/1.4-test-design-20260511.md
 */

import { describe, expect, test } from 'vitest';
import { readFileSync, statSync, existsSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { parse as parseYaml, parseAllDocuments } from 'yaml';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
const REPO_ROOT = resolve(__dirname, '..', '..', '..');

const repoPath = (rel: string): string => resolve(REPO_ROOT, rel);
const repoFileExists = (rel: string): boolean => existsSync(repoPath(rel));
const readRepoFile = (rel: string): string =>
  readFileSync(repoPath(rel), 'utf8');
const loadYaml = <T = unknown>(rel: string): T =>
  parseYaml(readRepoFile(rel)) as T;
const loadAllYaml = (rel: string): unknown[] =>
  parseAllDocuments(readRepoFile(rel)).map((d) => d.toJSON());

// Helper: walk a parsed YAML/JSON structure and yield every `[path, value]`
// where `value` is a primitive (string/number/boolean). Used for negative
// "no plaintext password / no ingress block / no Tempo reference" sweeps.
function* walkPrimitives(
  obj: unknown,
  path: string[] = [],
): Generator<[string[], string | number | boolean]> {
  if (obj === null || obj === undefined) return;
  if (typeof obj === 'string' || typeof obj === 'number' || typeof obj === 'boolean') {
    yield [path, obj];
    return;
  }
  if (Array.isArray(obj)) {
    for (let i = 0; i < obj.length; i++) {
      yield* walkPrimitives(obj[i], [...path, String(i)]);
    }
    return;
  }
  if (typeof obj === 'object') {
    for (const [k, v] of Object.entries(obj as Record<string, unknown>)) {
      yield* walkPrimitives(v, [...path, k]);
    }
  }
}

