describe('AC1.C / T11: CI extension (.github/workflows/infra-lint.yml)', () => {
  const path = '.github/workflows/infra-lint.yml';

  test('1.4-UNIT-240: helm-lint-observability job declares matrix of all 6 charts (M-2)', () => {
    const wf = loadYaml<any>(path);
    const job = wf?.jobs?.['helm-lint-observability'];
    expect(job).toBeDefined();
    const matrix = job?.strategy?.matrix?.chart ?? [];
    for (const c of ['kube-prometheus-stack', 'loki', 'promtail', 'otel-collector', 'jaeger', 'sample-otel-app']) {
      expect(matrix).toContain(c);
    }
    expect(matrix.length).toBeGreaterThanOrEqual(6);
  });

  test('1.4-UNIT-241: helm-lint-observability runs dependency update + lint + template|kubeconform', () => {
    const text = readRepoFile(path);
    expect(text).toMatch(/helm\s+dependency\s+update/);
    expect(text).toMatch(/helm\s+lint/);
    expect(text).toMatch(/helm\s+template[\s\S]+kubeconform/);
  });

  test('1.4-UNIT-242: dashboard-schema-validate job exists', () => {
    const wf = loadYaml<any>(path);
    expect(wf?.jobs?.['dashboard-schema-validate']).toBeDefined();
  });

  test('1.4-UNIT-243: paths filter includes infra/**, apps/sample-otel-app/**, .github/workflows/infra-lint.yml', () => {
    const wf = loadYaml<any>(path);
    const trigger = wf?.on?.pull_request ?? wf?.on?.push ?? wf?.on?.['true']; // YAML 1.1 'on' parses as boolean true
    // Try multiple shapes
    const paths: string[] =
      wf?.on?.pull_request?.paths ?? wf?.on?.push?.paths ?? trigger?.paths ?? [];
    const collected = paths.length > 0 ? paths : (() => {
      // Walk every paths array under any trigger
      const out: string[] = [];
      for (const triggerName of Object.keys(wf?.on ?? {})) {
        const node = wf.on[triggerName];
        if (Array.isArray(node?.paths)) out.push(...node.paths);
      }
      return out;
    })();
    expect(collected).toEqual(
      expect.arrayContaining(['infra/**', 'apps/sample-otel-app/**', '.github/workflows/infra-lint.yml']),
    );
  });

  test('1.4-UNIT-244: concurrency block reused from 1.3', () => {
    const wf = loadYaml<any>(path);
    expect(wf?.concurrency?.group).toMatch(/infra-lint-/);
    // cancel-in-progress is a GHA expression; tolerate either string form
    expect(String(wf?.concurrency?.['cancel-in-progress'])).toMatch(/pull_request/);
  });

  test('1.4-UNIT-245: 1.3 baseline jobs are NOT removed (still referenced in workflow)', () => {
    const wf = loadYaml<any>(path);
    // Story 1.3 introduced these 4 job IDs. Story 1.4 must add jobs only.
    for (const baseline of ['terraform-fmt', 'terraform-validate', 'tflint', 'helm-lint-api-gateway']) {
      // Tolerate alternate names by walking all job keys for substring match.
      const found = Object.keys(wf?.jobs ?? {}).some((k) =>
        k === baseline || k.replace(/-/g, '').includes(baseline.replace(/-/g, '')),
      );
      expect(found, `missing 1.3 baseline job similar to "${baseline}"`).toBe(true);
    }
  });
});

